async Task RunAsync(string name, Func<Task> action)
{
    try { await action(); passed++; Console.WriteLine(JsonSerializer.Serialize(new { name, passed = true })); }
    catch (Exception error) { failures.Add(name + ": " + error.GetType().FullName + ": " + error.Message); Console.WriteLine(JsonSerializer.Serialize(new { name, passed = false, error = error.GetType().FullName, error.Message })); }
}
static string Hash(string file) => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file))).ToLowerInvariant();
